values ('23c11da2-1b25-53b5-bdb4-77ce439bdb9f', null, '3_4_sit_up', 'Abdominal 3/4 (Sit-Up parcial)', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/3_4_sit_up-0.webp', 'Deite no chão com os joelhos flexionados e os pés presos.
Mãos atrás ou ao lado da cabeça, costas apoiadas no chão.
Flexione quadril e coluna até o tronco ficar perpendicular ao chão.
Volte descendo apenas ¾ do caminho e repita.', '{"progressionTree":"3_4_sit_up","progressionLevel":1,"maxLevel":5,"groups":["core"],"catalog_no":1,"source_id":"3_4_Sit-Up","steps":["Deite no chão com os joelhos flexionados e os pés presos.","Mãos atrás ou ao lado da cabeça, costas apoiadas no chão.","Flexione quadril e coluna até o tronco ficar perpendicular ao chão.","Volte descendo apenas ¾ do caminho e repita."],"tip":"Desça só ¾ do caminho para manter o abdômen sob tensão o tempo todo.","media_keys":["exercises/cali/3_4_sit_up-0.webp","exercises/cali/3_4_sit_up-1.webp"]}'::jsonb)
