values ('a251d609-49e9-570e-8aa6-93d6110c2313', null, 'air_bike', 'Bicicleta no ar (Air Bike)', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/air_bike-0.webp', 'Deitado, lombar colada no chão, mãos ao lado da cabeça e ombros elevados como num abdominal.
Joelhos a 90° com as canelas paralelas ao chão.
Pedale: estenda a perna direita enquanto traz o joelho esquerdo e aproxime o cotovelo direito dele, expirando.
Alterne os lados continuamente até completar as repetições.', '{"progressionTree":"air_bike","progressionLevel":1,"maxLevel":5,"groups":["core"],"catalog_no":3,"source_id":"Air_Bike","steps":["Deitado, lombar colada no chão, mãos ao lado da cabeça e ombros elevados como num abdominal.","Joelhos a 90° com as canelas paralelas ao chão.","Pedale: estenda a perna direita enquanto traz o joelho esquerdo e aproxime o cotovelo direito dele, expirando.","Alterne os lados continuamente até completar as repetições."],"tip":"Gire o tronco de verdade — leve o ombro ao joelho, não só o cotovelo.","media_keys":["exercises/cali/air_bike-0.webp","exercises/cali/air_bike-1.webp"]}'::jsonb)
