values ('d1601d26-ca8c-5d1c-85aa-fdc854abfc37', null, 'alternate_heel_touchers', 'Toque alternado nos calcanhares', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/alternate_heel_touchers-0.webp', 'Deitado com os joelhos flexionados, pés no chão afastados ~50 cm e braços ao lado do corpo.
Eleve levemente o tronco e incline para a direita até tocar o calcanhar direito; segure 1 s.
Volte ao centro e repita para a esquerda. Os dois lados contam 1 repetição.', '{"progressionTree":"alternate_heel_touchers","progressionLevel":1,"maxLevel":5,"groups":["core"],"catalog_no":4,"source_id":"Alternate_Heel_Touchers","steps":["Deitado com os joelhos flexionados, pés no chão afastados ~50 cm e braços ao lado do corpo.","Eleve levemente o tronco e incline para a direita até tocar o calcanhar direito; segure 1 s.","Volte ao centro e repita para a esquerda. Os dois lados contam 1 repetição."],"tip":"Flexione lateralmente o tronco; o pescoço fica relaxado.","media_keys":["exercises/cali/alternate_heel_touchers-0.webp","exercises/cali/alternate_heel_touchers-1.webp"]}'::jsonb)
