values ('2863f5f4-5d05-5d0d-bdb4-6b6d1c2ed498', null, 'alternate_leg_diagonal_bound', 'Salto diagonal alternado (Bound)', 'calisthenics', 'reps', 'beginner', array['conditioning','strength']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/alternate_leg_diagonal_bound-0.webp', 'Fique em base confortável com um pé ligeiramente à frente.
Impulsione com a perna da frente levando o joelho oposto para frente e para cima.
Salte em diagonal cobrindo a maior distância possível para o lado.
Alterne as pernas a cada salto (uma linha no chão ajuda a medir a distância).', '{"progressionTree":"alternate_leg_diagonal_bound","progressionLevel":1,"maxLevel":5,"groups":["plyo","legs"],"catalog_no":5,"source_id":"Alternate_Leg_Diagonal_Bound","steps":["Fique em base confortável com um pé ligeiramente à frente.","Impulsione com a perna da frente levando o joelho oposto para frente e para cima.","Salte em diagonal cobrindo a maior distância possível para o lado.","Alterne as pernas a cada salto (uma linha no chão ajuda a medir a distância)."],"tip":"Impulsione forte e aterrisse amortecendo com o joelho semiflexionado.","media_keys":["exercises/cali/alternate_leg_diagonal_bound-0.webp","exercises/cali/alternate_leg_diagonal_bound-1.webp"]}'::jsonb)
