values ('c560694c-3537-5cc5-8412-ba15ebfed8a1', null, 'band_assisted_pull_up', 'Barra fixa assistida com elástico', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Barra fixa','Elástico']::text[], 'exercises/cali/band_assisted_pull_up-0.webp', 'Prenda o elástico no centro da barra e apoie um joelho dobrado no laço.
Pegada média a aberta na barra.
Puxe o corpo contraindo o dorsal e levando os cotovelos ao lado do corpo até o queixo passar a barra.
Desça com controle, sem balanço.', '{"progressionTree":"band_assisted_pull_up","progressionLevel":1,"maxLevel":5,"groups":["back"],"catalog_no":6,"source_id":"Band_Assisted_Pull-Up","steps":["Prenda o elástico no centro da barra e apoie um joelho dobrado no laço.","Pegada média a aberta na barra.","Puxe o corpo contraindo o dorsal e levando os cotovelos ao lado do corpo até o queixo passar a barra.","Desça com controle, sem balanço."],"tip":"Troque por elásticos mais finos conforme evolui até fazer a barra livre.","media_keys":["exercises/cali/band_assisted_pull_up-0.webp","exercises/cali/band_assisted_pull_up-1.webp"]}'::jsonb)
