values ('24138015-7e4c-56cf-acad-0a8c0bcc05a1', null, 'bench_dips', 'Mergulho no banco (Bench Dips)', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Banco']::text[], 'exercises/cali/bench_dips-0.webp', 'De costas para o banco, apoie as mãos na borda na largura dos ombros, braços estendidos e pernas à frente.
Flexione os cotovelos e desça até o braço formar pouco menos de 90°.
Empurre com o tríceps de volta à posição inicial.', '{"progressionTree":"bench_dips","progressionLevel":1,"maxLevel":5,"groups":["triceps"],"catalog_no":7,"source_id":"Bench_Dips","steps":["De costas para o banco, apoie as mãos na borda na largura dos ombros, braços estendidos e pernas à frente.","Flexione os cotovelos e desça até o braço formar pouco menos de 90°.","Empurre com o tríceps de volta à posição inicial."],"tip":"Cotovelos apontando para trás e próximos; quadril perto do banco.","media_keys":["exercises/cali/bench_dips-0.webp","exercises/cali/bench_dips-1.webp"]}'::jsonb)
