values ('30423d5a-a4e6-59b3-931f-db18f8e9fe42', null, 'box_skip', 'Skip em caixas', 'calisthenics', 'reps', 'beginner', array['conditioning','strength']::goal_kind[], array['Caixa / plataforma']::text[], 'exercises/cali/box_skip-0.webp', 'Alinhe caixas a ~2,5 m de distância; comece de frente para a primeira com uma perna atrás.
