values ('740a4c8a-3182-5a2d-8da9-02251255c44d', null, 'carioca_quick_step', 'Passo carioca rápido', 'calisthenics', 'reps', 'beginner', array['conditioning','strength']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/carioca_quick_step-0.webp', 'Pés próximos e braço esquerdo para cima, em postura atlética relaxada.
Com o pé direito, dê um passo rápido por trás e eleve o joelho.
Movimente os braços junto com o joelho e desloque-se lateralmente.', '{"progressionTree":"carioca_quick_step","progressionLevel":1,"maxLevel":5,"groups":["plyo","legs"],"catalog_no":20,"source_id":"Carioca_Quick_Step","steps":["Pés próximos e braço esquerdo para cima, em postura atlética relaxada.","Com o pé direito, dê um passo rápido por trás e eleve o joelho.","Movimente os braços junto com o joelho e desloque-se lateralmente."],"tip":"Olhe sempre para frente e não gire os pés durante o deslocamento.","media_keys":["exercises/cali/carioca_quick_step-0.webp","exercises/cali/carioca_quick_step-1.webp"]}'::jsonb)
