values ('95cd6cc1-40d6-55d7-a1dd-107cdee2b71f', null, 'clock_push_up', 'Flexão relógio (Clock Push-Up)', 'calisthenics', 'reps', 'intermediate', array['conditioning','strength']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/clock_push_up-0.webp', 'Em posição de flexão, braços estendidos e mãos na largura dos ombros.
Desça flexionando os cotovelos até o peito se aproximar do chão.
Empurre explosivamente até sair do chão, deslocando o corpo ~30° para o lado.
Repita girando até voltar ao ponto de partida.', '{"progressionTree":"clock_push_up","progressionLevel":3,"maxLevel":5,"groups":["chest","plyo"],"catalog_no":22,"source_id":"Clock_Push-Up","steps":["Em posição de flexão, braços estendidos e mãos na largura dos ombros.","Desça flexionando os cotovelos até o peito se aproximar do chão.","Empurre explosivamente até sair do chão, deslocando o corpo ~30° para o lado.","Repita girando até voltar ao ponto de partida."],"tip":"Corpo reto do início ao fim; gire ~30° a cada salto.","media_keys":["exercises/cali/clock_push_up-0.webp","exercises/cali/clock_push_up-1.webp"]}'::jsonb)
