values ('1f77e20e-3da3-5d79-85ef-23e8d133c55f', null, 'cocoons', 'Casulo (Cocoons)', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/cocoons-0.webp', 'Deitado de costas, pernas estendidas e braços estendidos atrás da cabeça.
Traga os joelhos ao peito tirando os glúteos do chão enquanto flexiona a coluna e traz os braços por cima da cabeça.
Pausa breve e volte à posição inicial.', '{"progressionTree":"cocoons","progressionLevel":1,"maxLevel":5,"groups":["core"],"catalog_no":23,"source_id":"Cocoons","steps":["Deitado de costas, pernas estendidas e braços estendidos atrás da cabeça.","Traga os joelhos ao peito tirando os glúteos do chão enquanto flexiona a coluna e traz os braços por cima da cabeça.","Pausa breve e volte à posição inicial."],"tip":"Junte joelhos e braços ao mesmo tempo, como se fechasse um casulo.","media_keys":["exercises/cali/cocoons-0.webp","exercises/cali/cocoons-1.webp"]}'::jsonb)
