values ('f76186d3-f07f-5685-984b-a40ca95315bc', null, 'cross_body_crunch', 'Abdominal cruzado (Cross-Body Crunch)', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/cross_body_crunch-0.webp', 'Deitado, joelhos flexionados a ~60°, pés no chão e mãos soltas atrás da cabeça.
Suba levando o cotovelo e ombro direitos em direção ao joelho esquerdo, que vem ao encontro, expirando.
Volte inspirando e repita para o outro lado, alternando.', '{"progressionTree":"cross_body_crunch","progressionLevel":1,"maxLevel":5,"groups":["core"],"catalog_no":24,"source_id":"Cross-Body_Crunch","steps":["Deitado, joelhos flexionados a ~60°, pés no chão e mãos soltas atrás da cabeça.","Suba levando o cotovelo e ombro direitos em direção ao joelho esquerdo, que vem ao encontro, expirando.","Volte inspirando e repita para o outro lado, alternando."],"tip":"Leve o ombro em direção ao joelho — o abdômen faz o trabalho, não o cotovelo.","media_keys":["exercises/cali/cross_body_crunch-0.webp","exercises/cali/cross_body_crunch-1.webp"]}'::jsonb)
