values ('443fbc54-f2eb-5df4-81f0-090ea3cbdf01', null, 'crunch_hands_overhead', 'Abdominal com braços estendidos acima da cabeça', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/crunch_hands_overhead-0.webp', 'Deitado, joelhos a ~60° e pés no chão; estenda os braços acima da cabeça com as palmas cruzadas.
Enrole o tronco tirando as escápulas do chão sem mover os braços; segure 1 s, expirando.
Desça devagar inspirando.', '{"progressionTree":"crunch_hands_overhead","progressionLevel":1,"maxLevel":5,"groups":["core"],"catalog_no":25,"source_id":"Crunch_-_Hands_Overhead","steps":["Deitado, joelhos a ~60° e pés no chão; estenda os braços acima da cabeça com as palmas cruzadas.","Enrole o tronco tirando as escápulas do chão sem mover os braços; segure 1 s, expirando.","Desça devagar inspirando."],"tip":"Braços alinhados com cabeça e pescoço durante todo o movimento.","media_keys":["exercises/cali/crunch_hands_overhead-0.webp","exercises/cali/crunch_hands_overhead-1.webp"]}'::jsonb)
