values ('e2c31c67-88a1-57f9-b083-417c5e53ffe1', null, 'crunches', 'Abdominal supra (Crunch)', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/crunches-0.webp', 'Deitado, pés no chão e joelhos flexionados; mãos ao lado da cabeça, sem entrelaçar os dedos.
Pressione a lombar no chão e enrole os ombros para cima contraindo o abdômen, expirando.
Segure a contração 1 s no topo.
Desça devagar inspirando, sem usar impulso.', '{"progressionTree":"crunches","progressionLevel":1,"maxLevel":5,"groups":["core"],"catalog_no":26,"source_id":"Crunches","steps":["Deitado, pés no chão e joelhos flexionados; mãos ao lado da cabeça, sem entrelaçar os dedos.","Pressione a lombar no chão e enrole os ombros para cima contraindo o abdômen, expirando.","Segure a contração 1 s no topo.","Desça devagar inspirando, sem usar impulso."],"tip":"Pressione a lombar no chão; ombros sobem só ~10 cm.","media_keys":["exercises/cali/crunches-0.webp","exercises/cali/crunches-1.webp"]}'::jsonb)
