values ('99131cde-c813-5c25-ab63-cc4307c10e89', null, 'dead_bug', 'Dead Bug (inseto morto)', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/dead_bug-0.webp', 'Deitado de costas com os braços estendidos para o teto.
Eleve pés, joelhos e quadril a 90°; expire forte e cole a lombar no chão.
Estenda uma perna até quase tocar o chão, mantendo a pelve e a lombar fixas.
Volte e repita do outro lado, alternando.', '{"progressionTree":"dead_bug","progressionLevel":1,"maxLevel":5,"groups":["core"],"catalog_no":27,"source_id":"Dead_Bug","steps":["Deitado de costas com os braços estendidos para o teto.","Eleve pés, joelhos e quadril a 90°; expire forte e cole a lombar no chão.","Estenda uma perna até quase tocar o chão, mantendo a pelve e a lombar fixas.","Volte e repita do outro lado, alternando."],"tip":"A lombar não pode sair do chão — se arquear, diminua a amplitude.","media_keys":["exercises/cali/dead_bug-0.webp","exercises/cali/dead_bug-1.webp"]}'::jsonb)
