values ('78a989e0-4bbf-52a9-9d78-3a7f0f6fabf1', null, 'decline_oblique_crunch', 'Abdominal oblíquo no banco declinado', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Banco']::text[], 'exercises/cali/decline_oblique_crunch-0.webp', 'Prenda as pernas no banco declinado e eleve o tronco a ~40° do chão.
Uma mão ao lado da cabeça e a outra na coxa.
Suba girando o tronco até o cotovelo encostar no joelho oposto; segure 1 s, expirando.
Desça devagar e, ao fim da série, troque de lado.', '{"progressionTree":"decline_oblique_crunch","progressionLevel":1,"maxLevel":5,"groups":["core"],"catalog_no":29,"source_id":"Decline_Oblique_Crunch","steps":["Prenda as pernas no banco declinado e eleve o tronco a ~40° do chão.","Uma mão ao lado da cabeça e a outra na coxa.","Suba girando o tronco até o cotovelo encostar no joelho oposto; segure 1 s, expirando.","Desça devagar e, ao fim da série, troque de lado."],"tip":"Gire o tronco de verdade para sentir o oblíquo.","media_keys":["exercises/cali/decline_oblique_crunch-0.webp","exercises/cali/decline_oblique_crunch-1.webp"]}'::jsonb)
