values ('cdc845f8-74f7-5e38-99fa-b918641de4de', null, 'decline_push_up', 'Flexão declinada (pés elevados)', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Caixa / plataforma']::text[], 'exercises/cali/decline_push_up-0.webp', 'Mãos no chão afastadas ~90 cm e pés sobre um banco ou caixa.
Desça até o peito quase tocar o chão, inspirando.
Empurre de volta contraindo o peito, expirando; pausa breve no topo.', '{"progressionTree":"decline_push_up","progressionLevel":1,"maxLevel":5,"groups":["chest"],"catalog_no":30,"source_id":"Decline_Push-Up","steps":["Mãos no chão afastadas ~90 cm e pés sobre um banco ou caixa.","Desça até o peito quase tocar o chão, inspirando.","Empurre de volta contraindo o peito, expirando; pausa breve no topo."],"tip":"Ênfase na parte alta do peito; não deixe o quadril cair.","media_keys":["exercises/cali/decline_push_up-0.webp","exercises/cali/decline_push_up-1.webp"]}'::jsonb)
