values ('583237e3-976b-5b68-975c-4182c40f47e1', null, 'depth_jump_leap', 'Salto em profundidade para caixa alta', 'calisthenics', 'reps', 'beginner', array['conditioning','strength']::goal_kind[], array['Caixa / plataforma']::text[], 'exercises/cali/depth_jump_leap-0.webp', 'Use duas caixas: uma de 30–40 cm e outra de 55–65 cm, a ~70 cm uma da outra.
Em pé sobre a caixa baixa, pés juntos na borda.
Caia da caixa e, ao tocar o chão, salte imediatamente com os dois pés.
Use braços e extensão total do corpo para aterrissar na caixa alta, amortecendo com as pernas.', '{"progressionTree":"depth_jump_leap","progressionLevel":1,"maxLevel":5,"groups":["plyo","legs"],"catalog_no":32,"source_id":"Depth_Jump_Leap","steps":["Use duas caixas: uma de 30–40 cm e outra de 55–65 cm, a ~70 cm uma da outra.","Em pé sobre a caixa baixa, pés juntos na borda.","Caia da caixa e, ao tocar o chão, salte imediatamente com os dois pés.","Use braços e extensão total do corpo para aterrissar na caixa alta, amortecendo com as pernas."],"tip":"Minimize o tempo no chão: caia e salte imediatamente.","media_keys":["exercises/cali/depth_jump_leap-0.webp","exercises/cali/depth_jump_leap-1.webp"]}'::jsonb)
