values ('597db14c-01d0-5dc7-a51c-fbf7d3aa0aae', null, 'dips_chest_version', 'Paralelas – ênfase no peito', 'calisthenics', 'reps', 'intermediate', array['strength','hypertrophy']::goal_kind[], array['Paralelas']::text[], 'exercises/cali/dips_chest_version-0.webp', 'Sustente o corpo com os braços estendidos acima das paralelas.
