values ('5c1d35ae-9dd7-5f64-b1c6-ec550c38ec68', null, 'double_leg_butt_kick', 'Salto com calcanhares no glúteo', 'calisthenics', 'reps', 'beginner', array['conditioning','strength']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/double_leg_butt_kick-0.webp', 'Em pé com os joelhos levemente flexionados.
