values ('5f9bad8e-7020-5622-9130-ef6dcc5deef1', null, 'drop_push', 'Flexão com queda (Drop Push)', 'calisthenics', 'reps', 'intermediate', array['conditioning','strength']::goal_kind[], array['Caixa / plataforma']::text[], 'exercises/cali/drop_push-0.webp', 'Coloque duas plataformas baixas a 60–90 cm e fique em flexão com as mãos sobre elas.
