values ('72b8ab9d-0e0f-5c8c-9799-bf41fa286725', null, 'flat_bench_leg_pull_in', 'Recolhimento de pernas no banco', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Banco']::text[], 'exercises/cali/flat_bench_leg_pull_in-0.webp', 'Deite no banco (ou colchonete) com as pernas para fora da ponta e estendidas.
