values ('6b1a40a0-6358-58f9-a05f-fbedbeb5bc72', null, 'freehand_jump_squat', 'Agachamento com salto', 'calisthenics', 'reps', 'intermediate', array['conditioning','strength']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/freehand_jump_squat-0.webp', 'Braços cruzados no peito, pés na largura dos ombros, cabeça erguida e costas retas.
Agache até as coxas ficarem paralelas ao chão, inspirando.
Salte o mais alto possível impulsionando pela ponta dos pés, expirando.
Ao tocar o chão, agache e salte novamente.', '{"progressionTree":"freehand_jump_squat","progressionLevel":3,"maxLevel":5,"groups":["legs","plyo"],"catalog_no":44,"source_id":"Freehand_Jump_Squat","steps":["Braços cruzados no peito, pés na largura dos ombros, cabeça erguida e costas retas.","Agache até as coxas ficarem paralelas ao chão, inspirando.","Salte o mais alto possível impulsionando pela ponta dos pés, expirando.","Ao tocar o chão, agache e salte novamente."],"tip":"Aterrisse e já desça para o próximo salto, usando as coxas como molas.","media_keys":["exercises/cali/freehand_jump_squat-0.webp","exercises/cali/freehand_jump_squat-1.webp"]}'::jsonb)
