values ('df0d8b29-8e98-50a5-815a-b16458a03f36', null, 'front_box_jump', 'Salto frontal na caixa', 'calisthenics', 'reps', 'beginner', array['conditioning','strength']::goal_kind[], array['Caixa / plataforma']::text[], 'exercises/cali/front_box_jump-0.webp', 'Fique a 30–60 cm de uma caixa de altura adequada, pés na largura dos ombros.
Faça um meio agachamento levando os braços para trás.
Salte estendendo quadril, joelhos e tornozelos, levando os braços à frente e para cima.
Aterrisse na caixa com os joelhos flexionados, absorvendo o impacto.', '{"progressionTree":"front_box_jump","progressionLevel":1,"maxLevel":5,"groups":["plyo","legs"],"catalog_no":46,"source_id":"Front_Box_Jump","steps":["Fique a 30–60 cm de uma caixa de altura adequada, pés na largura dos ombros.","Faça um meio agachamento levando os braços para trás.","Salte estendendo quadril, joelhos e tornozelos, levando os braços à frente e para cima.","Aterrisse na caixa com os joelhos flexionados, absorvendo o impacto."],"tip":"Prefira descer da caixa caminhando, uma perna de cada vez.","media_keys":["exercises/cali/front_box_jump-0.webp","exercises/cali/front_box_jump-1.webp"]}'::jsonb)
