values ('07836558-3f95-5b38-99b6-360687eb2249', null, 'front_cone_hops_or_hurdle_hops', 'Saltos frontais sobre cones', 'calisthenics', 'reps', 'beginner', array['conditioning','strength']::goal_kind[], array['Cones / barreiras']::text[], 'exercises/cali/front_cone_hops_or_hurdle_hops-0.webp', 'Enfileire cones ou pequenas barreiras com ~1 m entre eles.
Fique em frente ao primeiro com os pés na largura dos ombros.
Salte com os dois pés por cima do cone balançando os braços.
Amorteça a aterrissagem e emende o salto sobre o próximo, até o fim da fila.', '{"progressionTree":"front_cone_hops_or_hurdle_hops","progressionLevel":1,"maxLevel":5,"groups":["plyo","legs"],"catalog_no":47,"source_id":"Front_Cone_Hops_or_hurdle_hops","steps":["Enfileire cones ou pequenas barreiras com ~1 m entre eles.","Fique em frente ao primeiro com os pés na largura dos ombros.","Salte com os dois pés por cima do cone balançando os braços.","Amorteça a aterrissagem e emende o salto sobre o próximo, até o fim da fila."],"tip":"Aterrisse e salte de novo imediatamente (rebote).","media_keys":["exercises/cali/front_cone_hops_or_hurdle_hops-0.webp","exercises/cali/front_cone_hops_or_hurdle_hops-1.webp"]}'::jsonb)
