values ('33fe6045-b63e-5f0c-b1b2-96f2907464d9', null, 'gironda_sternum_chins', 'Barra Gironda (barra ao esterno)', 'calisthenics', 'reps', 'intermediate', array['strength','hypertrophy']::goal_kind[], array['Barra fixa']::text[], 'exercises/cali/gironda_sternum_chins-0.webp', 'Pegada supinada na largura dos ombros, braços estendidos, peito aberto e corpo inclinado para trás.
