values ('a511b278-028c-5edb-98ae-5be7f53296ed', null, 'handstand_push_ups', 'Flexão em parada de mão (Handstand Push-Up)', 'calisthenics', 'reps', 'advanced', array['strength','hypertrophy']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/handstand_push_ups-0.webp', 'De costas para a parede, apoie as mãos no chão na largura dos ombros.
