values ('0aaf33fe-3bec-5812-ae80-ea2716db3643', null, 'hanging_pike', 'Pike suspenso na barra', 'calisthenics', 'reps', 'advanced', array['strength','hypertrophy']::goal_kind[], array['Barra fixa']::text[], 'exercises/cali/hanging_pike-0.webp', 'Suspenso na barra com pegada pronada um pouco mais aberta que os ombros, pernas juntas.
Joelhos a 90° com as coxas paralelas ao chão.
Leve as pernas para cima até as canelas quase tocarem a barra, expirando.
Desça devagar até a posição inicial.', '{"progressionTree":"hanging_pike","progressionLevel":5,"maxLevel":5,"groups":["core"],"catalog_no":53,"source_id":"Hanging_Pike","steps":["Suspenso na barra com pegada pronada um pouco mais aberta que os ombros, pernas juntas.","Joelhos a 90° com as coxas paralelas ao chão.","Leve as pernas para cima até as canelas quase tocarem a barra, expirando.","Desça devagar até a posição inicial."],"tip":"Desça o mais devagar possível — a fase excêntrica é o segredo.","media_keys":["exercises/cali/hanging_pike-0.webp","exercises/cali/hanging_pike-1.webp"]}'::jsonb)
