values ('dcc7db37-3fcc-5140-9cb0-6fc1995d62f9', null, 'hurdle_hops', 'Saltos sobre barreiras', 'calisthenics', 'reps', 'beginner', array['conditioning','strength']::goal_kind[], array['Cones / barreiras']::text[], 'exercises/cali/hurdle_hops-0.webp', 'Enfileire pequenas barreiras com ~1 m de distância.
Fique em frente à primeira com os pés na largura dos ombros.
Salte com os dois pés por cima, balançando os braços.
Amorteça e emende o salto na próxima barreira, até o fim.', '{"progressionTree":"hurdle_hops","progressionLevel":1,"maxLevel":5,"groups":["plyo","legs"],"catalog_no":54,"source_id":"Hurdle_Hops","steps":["Enfileire pequenas barreiras com ~1 m de distância.","Fique em frente à primeira com os pés na largura dos ombros.","Salte com os dois pés por cima, balançando os braços.","Amorteça e emende o salto na próxima barreira, até o fim."],"tip":"Use os braços para ganhar altura e emende os saltos.","media_keys":["exercises/cali/hurdle_hops-0.webp","exercises/cali/hurdle_hops-1.webp"]}'::jsonb)
