values ('c9b246a1-e624-5495-9591-323cf7a442b4', null, 'hyperextensions_back_extensions', 'Hiperextensão lombar no banco romano', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Banco']::text[], 'exercises/cali/hyperextensions_back_extensions-0.webp', 'De bruços no banco de hiperextensão, tornozelos presos e coxas sobre o apoio.
Corpo reto com os braços cruzados à frente ou atrás da cabeça.
Desça o tronco flexionando o quadril até sentir os posteriores alongarem, inspirando.
Suba devagar até alinhar o tronco, expirando.', '{"progressionTree":"hyperextensions_back_extensions","progressionLevel":1,"maxLevel":5,"groups":["back","legs"],"catalog_no":55,"source_id":"Hyperextensions_Back_Extensions","steps":["De bruços no banco de hiperextensão, tornozelos presos e coxas sobre o apoio.","Corpo reto com os braços cruzados à frente ou atrás da cabeça.","Desça o tronco flexionando o quadril até sentir os posteriores alongarem, inspirando.","Suba devagar até alinhar o tronco, expirando."],"tip":"Costas retas: pare antes de arredondar a coluna.","media_keys":["exercises/cali/hyperextensions_back_extensions-0.webp","exercises/cali/hyperextensions_back_extensions-1.webp"]}'::jsonb)
