values ('2ce733f4-398e-53e3-90a5-cb1143a0ec52', null, 'incline_push_up', 'Flexão inclinada (mãos elevadas)', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Banco']::text[], 'exercises/cali/incline_push_up-0.webp', 'De frente para um banco ou plataforma firme, mãos na borda um pouco mais abertas que os ombros.
Pés para trás, corpo e braços retos.
Desça o peito até a borda flexionando os braços, com o corpo alinhado.
Empurre até estender os braços.', '{"progressionTree":"incline_push_up","progressionLevel":1,"maxLevel":5,"groups":["chest"],"catalog_no":57,"source_id":"Incline_Push-Up","steps":["De frente para um banco ou plataforma firme, mãos na borda um pouco mais abertas que os ombros.","Pés para trás, corpo e braços retos.","Desça o peito até a borda flexionando os braços, com o corpo alinhado.","Empurre até estender os braços."],"tip":"Ótima progressão para iniciantes: quanto mais alto o apoio, mais fácil.","media_keys":["exercises/cali/incline_push_up-0.webp","exercises/cali/incline_push_up-1.webp"]}'::jsonb)
