values ('cfaff3f8-a792-5d72-a6f8-fb732ae5a9fa', null, 'incline_push_up_close_grip', 'Flexão inclinada fechada', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Banco']::text[], 'exercises/cali/incline_push_up_close_grip-0.webp', 'De frente para uma barra ou plataforma firme, mãos juntas sobre ela.
