values ('0862f9ee-ed40-5511-b634-6fd975f7d0b7', null, 'kipping_muscle_up', 'Muscle-Up com impulso (Kipping) nas argolas', 'calisthenics', 'reps', 'intermediate', array['strength','hypertrophy']::goal_kind[], array['Argolas / suspensão']::text[], 'exercises/cali/kipping_muscle_up-0.webp', 'Segure as argolas com pegada falsa (base da palma sobre a argola).
