values ('9b37ee72-2b57-539c-a1a7-7e38142b5bbd', null, 'leg_lift', 'Flexão de perna em pé (glúteo/posterior)', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/leg_lift-0.webp', 'Em pé, apoie as mãos em algo firme para manter o equilíbrio.
Eleve uma perna para trás flexionando o joelho, como numa mesa flexora em pé, expirando.
Volte devagar inspirando; ao fim da série, troque de perna.', '{"progressionTree":"leg_lift","progressionLevel":1,"maxLevel":5,"groups":["legs"],"catalog_no":76,"source_id":"Leg_Lift","steps":["Em pé, apoie as mãos em algo firme para manter o equilíbrio.","Eleve uma perna para trás flexionando o joelho, como numa mesa flexora em pé, expirando.","Volte devagar inspirando; ao fim da série, troque de perna."],"tip":"Tronco ereto e perna de apoio estendida.","media_keys":["exercises/cali/leg_lift-0.webp","exercises/cali/leg_lift-1.webp"]}'::jsonb)
