values ('178a9831-706a-5642-9abb-78823fe997d0', null, 'leg_pull_in', 'Recolhimento de pernas no chão', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/leg_pull_in-0.webp', 'Deitado no colchonete, pernas estendidas e mãos ao lado do corpo ou sob os glúteos.
Flexione os joelhos e traga as coxas ao abdômen até os joelhos chegarem à altura do peito, expirando.
Volte estendendo as pernas, inspirando.', '{"progressionTree":"leg_pull_in","progressionLevel":1,"maxLevel":5,"groups":["core"],"catalog_no":77,"source_id":"Leg_Pull-In","steps":["Deitado no colchonete, pernas estendidas e mãos ao lado do corpo ou sob os glúteos.","Flexione os joelhos e traga as coxas ao abdômen até os joelhos chegarem à altura do peito, expirando.","Volte estendendo as pernas, inspirando."],"tip":"Contraia o abdômen e segure 1 s com os joelhos no peito.","media_keys":["exercises/cali/leg_pull_in-0.webp","exercises/cali/leg_pull_in-1.webp"]}'::jsonb)
