values ('808f986c-2232-5cdf-b3af-942134644311', null, 'linear_depth_jump', 'Salto em profundidade linear', 'calisthenics', 'reps', 'intermediate', array['conditioning','strength']::goal_kind[], array['Caixa / plataforma']::text[], 'exercises/cali/linear_depth_jump-0.webp', 'Use duas caixas a alguns passos uma da outra; suba em uma, de frente para a outra.
Caia suavemente no chão entre elas, flexionando joelhos e quadril.
Exploda estendendo quadril, joelhos e tornozelos e salte para a outra caixa.
Aterrisse macio, absorvendo o impacto com as pernas.', '{"progressionTree":"linear_depth_jump","progressionLevel":3,"maxLevel":5,"groups":["plyo","legs"],"catalog_no":78,"source_id":"Linear_Depth_Jump","steps":["Use duas caixas a alguns passos uma da outra; suba em uma, de frente para a outra.","Caia suavemente no chão entre elas, flexionando joelhos e quadril.","Exploda estendendo quadril, joelhos e tornozelos e salte para a outra caixa.","Aterrisse macio, absorvendo o impacto com as pernas."],"tip":"Caia e salte imediatamente; aterrisse macio na outra caixa.","media_keys":["exercises/cali/linear_depth_jump-0.webp","exercises/cali/linear_depth_jump-1.webp"]}'::jsonb)
