values ('05e8fa26-0255-5879-bea7-23a1b4be1605', null, 'london_bridges', 'London Bridges (descida na corda)', 'calisthenics', 'reps', 'intermediate', array['strength','hypertrophy']::goal_kind[], array['Corda']::text[], 'exercises/cali/london_bridges-0.webp', 'Prenda uma corda no alto e suba em uma plataforma firme logo abaixo, segurando a corda.
Mantendo o corpo reto, incline-se para trás descendo mão sobre mão até ficar perpendicular ao chão.
Volte subindo mão sobre mão até a posição inicial.', '{"progressionTree":"london_bridges","progressionLevel":3,"maxLevel":5,"groups":["back"],"catalog_no":79,"source_id":"London_Bridges","steps":["Prenda uma corda no alto e suba em uma plataforma firme logo abaixo, segurando a corda.","Mantendo o corpo reto, incline-se para trás descendo mão sobre mão até ficar perpendicular ao chão.","Volte subindo mão sobre mão até a posição inicial."],"tip":"Corpo reto como uma tábua durante toda a descida e subida.","media_keys":["exercises/cali/london_bridges-0.webp","exercises/cali/london_bridges-1.webp"]}'::jsonb)
