values ('b6e7e3e0-cc8f-5dc1-b4fa-70c7bac17cef', null, 'mixed_grip_chin', 'Barra fixa com pegada mista', 'calisthenics', 'reps', 'advanced', array['strength','hypertrophy']::goal_kind[], array['Barra fixa']::text[], 'exercises/cali/mixed_grip_chin-0.webp', 'Segure a barra pouco mais aberta que os ombros: uma palma para frente e a outra voltada para você.
