values ('a27b2465-2aba-5862-9053-2b31377a8846', null, 'oblique_crunches', 'Abdominal oblíquo com pés elevados', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Banco']::text[], 'exercises/cali/oblique_crunches-0.webp', 'Deitado com a lombar no chão e os pés apoiados numa superfície elevada.
Uma mão ao lado da cabeça e a outra no chão.
Eleve o ombro e o tronco até o cotovelo tocar o joelho oposto.
Desça e, ao fim da série, troque de lado.', '{"progressionTree":"oblique_crunches","progressionLevel":1,"maxLevel":5,"groups":["core"],"catalog_no":84,"source_id":"Oblique_Crunches","steps":["Deitado com a lombar no chão e os pés apoiados numa superfície elevada.","Uma mão ao lado da cabeça e a outra no chão.","Eleve o ombro e o tronco até o cotovelo tocar o joelho oposto.","Desça e, ao fim da série, troque de lado."],"tip":"Leve o cotovelo ao joelho oposto girando o tronco.","media_keys":["exercises/cali/oblique_crunches-0.webp","exercises/cali/oblique_crunches-1.webp"]}'::jsonb)
