values ('a75d2505-d4b7-5b54-acb2-aa137300843b', null, 'oblique_crunches_on_the_floor', 'Abdominal oblíquo deitado de lado', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/oblique_crunches_on_the_floor-0.webp', 'Deite sobre o lado direito com as pernas sobrepostas e joelhos levemente flexionados.
Mão esquerda atrás da cabeça.
Eleve o cotovelo esquerdo como num abdominal, com ênfase no oblíquo, expirando.
Segure 1 s, desça devagar e depois troque de lado.', '{"progressionTree":"oblique_crunches_on_the_floor","progressionLevel":1,"maxLevel":5,"groups":["core"],"catalog_no":85,"source_id":"Oblique_Crunches_-_On_The_Floor","steps":["Deite sobre o lado direito com as pernas sobrepostas e joelhos levemente flexionados.","Mão esquerda atrás da cabeça.","Eleve o cotovelo esquerdo como num abdominal, com ênfase no oblíquo, expirando.","Segure 1 s, desça devagar e depois troque de lado."],"tip":"Suba o mais alto que puder e segure 1 s.","media_keys":["exercises/cali/oblique_crunches_on_the_floor-0.webp","exercises/cali/oblique_crunches_on_the_floor-1.webp"]}'::jsonb)
