values ('3507ef4d-77d8-55b4-810d-046368a347ef', null, 'one_arm_chin_up', 'Barra a um braço (com toalha de apoio)', 'calisthenics', 'reps', 'advanced', array['strength','hypertrophy']::goal_kind[], array['Barra fixa']::text[], 'exercises/cali/one_arm_chin_up-0.webp', 'Passe uma toalha pela barra; uma mão segura a barra (palma para você) e a outra a toalha.
Incline o tronco ~30° para trás com o peito aberto.
Puxe até a barra tocar a parte alta do peito, levando ombros e braços para baixo e para trás, expirando.
Segure 1 s e desça devagar. Troque de braço.', '{"progressionTree":"one_arm_chin_up","progressionLevel":5,"maxLevel":5,"groups":["back","biceps"],"catalog_no":86,"source_id":"One_Arm_Chin-Up","steps":["Passe uma toalha pela barra; uma mão segura a barra (palma para você) e a outra a toalha.","Incline o tronco ~30° para trás com o peito aberto.","Puxe até a barra tocar a parte alta do peito, levando ombros e braços para baixo e para trás, expirando.","Segure 1 s e desça devagar. Troque de braço."],"tip":"Use a mão na toalha só como auxílio; progrida reduzindo a ajuda.","media_keys":["exercises/cali/one_arm_chin_up-0.webp","exercises/cali/one_arm_chin_up-1.webp"]}'::jsonb)
