values ('705a1f9d-132b-5dd7-b796-8cd1673a4842', null, 'parallel_bar_dip', 'Mergulho nas paralelas', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Paralelas']::text[], 'exercises/cali/parallel_bar_dip-0.webp', 'Entre as paralelas, apoie uma mão em cada barra e dê um pequeno impulso até travar os braços.
