values ('4b6e4c8c-43e8-5e61-ba82-b15717619b89', null, 'plyo_push_up', 'Flexão pliométrica', 'calisthenics', 'reps', 'beginner', array['conditioning','strength']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/plyo_push_up-0.webp', 'Em posição de flexão, braços estendidos na largura dos ombros e corpo reto.
Desça flexionando os cotovelos até o peito se aproximar do chão.
Empurre explosivamente até as mãos saírem do chão.
Aterrisse com os cotovelos levemente flexionados e repita.', '{"progressionTree":"plyo_push_up","progressionLevel":1,"maxLevel":5,"groups":["chest","plyo"],"catalog_no":89,"source_id":"Plyo_Push-up","steps":["Em posição de flexão, braços estendidos na largura dos ombros e corpo reto.","Desça flexionando os cotovelos até o peito se aproximar do chão.","Empurre explosivamente até as mãos saírem do chão.","Aterrisse com os cotovelos levemente flexionados e repita."],"tip":"Empurre tão rápido que as mãos saiam do chão; adicione palmas para dificultar.","media_keys":["exercises/cali/plyo_push_up-0.webp","exercises/cali/plyo_push_up-1.webp"]}'::jsonb)
