values ('53dadbd8-057f-547e-8832-bb1bbf06ca83', null, 'push_up_to_side_plank', 'Flexão com prancha lateral', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/push_up_to_side_plank-0.webp', 'Em posição de flexão, mãos um pouco mais abertas que os ombros.
