values ('12f565d3-09ed-5446-9d6c-e7a64d994583', null, 'pushups', 'Flexão de braço (Push-Up)', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/pushups-0.webp', 'De bruços, mãos afastadas ~90 cm e tronco elevado com os braços estendidos.
Desça até o peito quase tocar o chão, inspirando.
Empurre de volta contraindo o peito, expirando; pausa breve no topo.', '{"progressionTree":"pushups","progressionLevel":1,"maxLevel":5,"groups":["chest"],"catalog_no":95,"source_id":"Pushups","steps":["De bruços, mãos afastadas ~90 cm e tronco elevado com os braços estendidos.","Desça até o peito quase tocar o chão, inspirando.","Empurre de volta contraindo o peito, expirando; pausa breve no topo."],"tip":"Corpo em prancha, cotovelos a ~45° do tronco.","media_keys":["exercises/cali/pushups-0.webp","exercises/cali/pushups-1.webp"]}'::jsonb)
