values ('f94839e1-f86a-5632-a2c8-3aa19d93bf41', null, 'pushups_close_and_wide_hand_positions', 'Flexão variando pegada (fechada e aberta)', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/pushups_close_and_wide_hand_positions-0.webp', 'Em prancha alta com as mãos abertas (mais que os ombros) ou fechadas (menos que os ombros).
Desça até o peito quase tocar o chão, inspirando.
Empurre contraindo o peito, expirando; pausa de 1 s no topo.', '{"progressionTree":"pushups_close_and_wide_hand_positions","progressionLevel":1,"maxLevel":5,"groups":["chest","triceps"],"catalog_no":96,"source_id":"Pushups_Close_and_Wide_Hand_Positions","steps":["Em prancha alta com as mãos abertas (mais que os ombros) ou fechadas (menos que os ombros).","Desça até o peito quase tocar o chão, inspirando.","Empurre contraindo o peito, expirando; pausa de 1 s no topo."],"tip":"Alterne a largura das mãos entre as séries para variar o estímulo.","media_keys":["exercises/cali/pushups_close_and_wide_hand_positions-0.webp","exercises/cali/pushups_close_and_wide_hand_positions-1.webp"]}'::jsonb)
