values ('7130112c-d052-5893-9840-31aad9ee8ebc', null, 'quick_leap', 'Salto rápido da caixa (Quick Leap)', 'calisthenics', 'reps', 'beginner', array['conditioning','strength']::goal_kind[], array['Caixa / plataforma']::text[], 'exercises/cali/quick_leap-0.webp', 'Fique de frente para a caixa a 30–60 cm da borda.
Salte para cima da caixa usando o quadril, aterrissando com os dois pés.
Imediatamente estenda todo o corpo, balance os braços acima da cabeça e salte da caixa.
Amorteça a aterrissagem com as pernas.', '{"progressionTree":"quick_leap","progressionLevel":1,"maxLevel":5,"groups":["plyo","legs"],"catalog_no":97,"source_id":"Quick_Leap","steps":["Fique de frente para a caixa a 30–60 cm da borda.","Salte para cima da caixa usando o quadril, aterrissando com os dois pés.","Imediatamente estenda todo o corpo, balance os braços acima da cabeça e salte da caixa.","Amorteça a aterrissagem com as pernas."],"tip":"Pés chapados e pernas flexionadas ao aterrissar na caixa.","media_keys":["exercises/cali/quick_leap-0.webp","exercises/cali/quick_leap-1.webp"]}'::jsonb)
