values ('b0202809-6e16-5636-ae65-7c08e8164f8e', null, 'reverse_crunch', 'Abdominal reverso', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/reverse_crunch-0.webp', 'Deitado, braços ao lado do tronco com as palmas no chão.
Coxas perpendiculares ao chão e pés juntos.
Traga as pernas em direção ao tronco enrolando a pelve e tirando o quadril do chão.
Segure 1 s e volte devagar.', '{"progressionTree":"reverse_crunch","progressionLevel":1,"maxLevel":5,"groups":["core"],"catalog_no":98,"source_id":"Reverse_Crunch","steps":["Deitado, braços ao lado do tronco com as palmas no chão.","Coxas perpendiculares ao chão e pés juntos.","Traga as pernas em direção ao tronco enrolando a pelve e tirando o quadril do chão.","Segure 1 s e volte devagar."],"tip":"Braços parados; enrole a pelve trazendo os joelhos ao peito.","media_keys":["exercises/cali/reverse_crunch-0.webp","exercises/cali/reverse_crunch-1.webp"]}'::jsonb)
