values ('bf644763-2dce-51f2-80c6-13c3453c6584', null, 'ring_dips', 'Mergulho nas argolas', 'calisthenics', 'reps', 'intermediate', array['strength','hypertrophy']::goal_kind[], array['Argolas / suspensão']::text[], 'exercises/cali/ring_dips-0.webp', 'Segure uma argola em cada mão e dê um pequeno impulso até travar os braços.
Flexione os cotovelos e desça até os braços passarem de 90°, com boa postura.
Estenda os cotovelos voltando ao topo.', '{"progressionTree":"ring_dips","progressionLevel":3,"maxLevel":5,"groups":["triceps","chest"],"catalog_no":99,"source_id":"Ring_Dips","steps":["Segure uma argola em cada mão e dê um pequeno impulso até travar os braços.","Flexione os cotovelos e desça até os braços passarem de 90°, com boa postura.","Estenda os cotovelos voltando ao topo."],"tip":"Argolas junto ao corpo para estabilizar; sem balanço.","media_keys":["exercises/cali/ring_dips-0.webp","exercises/cali/ring_dips-1.webp"]}'::jsonb)
