values ('b0412f5f-a988-5b15-93c8-a469e9743413', null, 'rocket_jump', 'Salto foguete (Rocket Jump)', 'calisthenics', 'reps', 'beginner', array['conditioning','strength']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/rocket_jump-0.webp', 'Em pé, pés na largura dos ombros e braços junto ao corpo.
Agache até a metade e exploda para cima o mais alto possível.
Estenda todo o corpo levando os braços acima da cabeça.
Aterrisse amortecendo com as pernas.', '{"progressionTree":"rocket_jump","progressionLevel":1,"maxLevel":5,"groups":["plyo","legs"],"catalog_no":100,"source_id":"Rocket_Jump","steps":["Em pé, pés na largura dos ombros e braços junto ao corpo.","Agache até a metade e exploda para cima o mais alto possível.","Estenda todo o corpo levando os braços acima da cabeça.","Aterrisse amortecendo com as pernas."],"tip":"Estenda o corpo inteiro e alcance o mais alto que puder.","media_keys":["exercises/cali/rocket_jump-0.webp","exercises/cali/rocket_jump-1.webp"]}'::jsonb)
