values ('f9306187-2a06-500c-8f2f-66c2e2f83eed', null, 'scissors_jump', 'Salto tesoura (afundo com salto)', 'calisthenics', 'reps', 'beginner', array['conditioning','strength']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/scissors_jump-0.webp', 'Em posição de afundo: pé da frente com joelho flexionado e joelho de trás quase no chão.
Salte o mais alto possível estendendo as pernas e balançando os braços.
No ar, troque as pernas: a da frente vai para trás e vice-versa.
Aterrisse em afundo amortecendo e repita.', '{"progressionTree":"scissors_jump","progressionLevel":1,"maxLevel":5,"groups":["plyo","legs"],"catalog_no":105,"source_id":"Scissors_Jump","steps":["Em posição de afundo: pé da frente com joelho flexionado e joelho de trás quase no chão.","Salte o mais alto possível estendendo as pernas e balançando os braços.","No ar, troque as pernas: a da frente vai para trás e vice-versa.","Aterrisse em afundo amortecendo e repita."],"tip":"Joelho da frente alinhado ao pé na aterrissagem.","media_keys":["exercises/cali/scissors_jump-0.webp","exercises/cali/scissors_jump-1.webp"]}'::jsonb)
