values ('abf9915a-fb8f-5afd-b8a4-b9910bf2522a', null, 'seated_flat_bench_leg_pull_in', 'Recolhimento sentado no banco', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Banco']::text[], 'exercises/cali/seated_flat_bench_leg_pull_in-0.webp', 'Sentado no banco, pernas estendidas à frente levemente abaixo da linha do banco e mãos nas laterais.
Tronco inclinado ~45° para trás.
Traga os joelhos em sua direção enquanto aproxima o tronco deles, expirando.
Pausa de 1 s e volte inspirando.', '{"progressionTree":"seated_flat_bench_leg_pull_in","progressionLevel":1,"maxLevel":5,"groups":["core"],"catalog_no":106,"source_id":"Seated_Flat_Bench_Leg_Pull-In","steps":["Sentado no banco, pernas estendidas à frente levemente abaixo da linha do banco e mãos nas laterais.","Tronco inclinado ~45° para trás.","Traga os joelhos em sua direção enquanto aproxima o tronco deles, expirando.","Pausa de 1 s e volte inspirando."],"tip":"Aproxime tronco e joelhos ao mesmo tempo.","media_keys":["exercises/cali/seated_flat_bench_leg_pull_in-0.webp","exercises/cali/seated_flat_bench_leg_pull_in-1.webp"]}'::jsonb)
