values ('74e69858-9067-5703-9b8d-c8b51fe00118', null, 'seated_leg_tucks', 'Encolhimento de pernas sentado no chão', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/seated_leg_tucks-0.webp', 'Sentado, pernas estendidas à frente pouco acima do chão e mãos apoiadas ao lado do quadril.
Tronco inclinado ~45° para trás.
Traga os joelhos ao peito aproximando o tronco deles, expirando.
Pausa de 1 s e estenda de volta.', '{"progressionTree":"seated_leg_tucks","progressionLevel":1,"maxLevel":5,"groups":["core"],"catalog_no":107,"source_id":"Seated_Leg_Tucks","steps":["Sentado, pernas estendidas à frente pouco acima do chão e mãos apoiadas ao lado do quadril.","Tronco inclinado ~45° para trás.","Traga os joelhos ao peito aproximando o tronco deles, expirando.","Pausa de 1 s e estenda de volta."],"tip":"Equilibre-se nos glúteos e mantenha o abdômen firme.","media_keys":["exercises/cali/seated_leg_tucks-0.webp","exercises/cali/seated_leg_tucks-1.webp"]}'::jsonb)
