values ('6b794203-4379-5f63-a7ba-c2db123f1ea2', null, 'side_bridge', 'Prancha lateral (Side Bridge)', 'calisthenics', 'hold', 'beginner', array['skill','endurance']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/side_bridge-0.webp', 'Deite de lado apoiado no antebraço, cotovelo sob o ombro e pernas estendidas sobrepostas.
Eleve o quadril do chão até o corpo formar uma linha reta.
Sustente pelo tempo indicado e troque de lado.', '{"progressionTree":"side_bridge","progressionLevel":1,"maxLevel":5,"groups":["core"],"catalog_no":108,"source_id":"Side_Bridge","steps":["Deite de lado apoiado no antebraço, cotovelo sob o ombro e pernas estendidas sobrepostas.","Eleve o quadril do chão até o corpo formar uma linha reta.","Sustente pelo tempo indicado e troque de lado."],"tip":"Quadril alto e corpo em linha reta da cabeça aos pés.","media_keys":["exercises/cali/side_bridge-0.webp","exercises/cali/side_bridge-1.webp"]}'::jsonb)
