values ('fe50464c-379c-5e06-ab5e-c671ec650918', null, 'side_jackknife', 'Canivete lateral (Side Jackknife)', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/side_jackknife-0.webp', 'Deite de lado, pernas estendidas sobrepostas, mão de cima atrás da cabeça e braço de baixo apoiado no chão.
Eleve ao mesmo tempo o tronco e a perna de cima, aproximando o cotovelo do joelho.
Desça devagar e, ao fim da série, troque de lado.', '{"progressionTree":"side_jackknife","progressionLevel":1,"maxLevel":5,"groups":["core"],"catalog_no":109,"source_id":"Side_Jackknife","steps":["Deite de lado, pernas estendidas sobrepostas, mão de cima atrás da cabeça e braço de baixo apoiado no chão.","Eleve ao mesmo tempo o tronco e a perna de cima, aproximando o cotovelo do joelho.","Desça devagar e, ao fim da série, troque de lado."],"tip":"Aproxime cotovelo e perna pela lateral, contraindo o oblíquo.","media_keys":["exercises/cali/side_jackknife-0.webp","exercises/cali/side_jackknife-1.webp"]}'::jsonb)
