values ('0b76cdf2-8051-5000-b867-4ccba3cf1c9b', null, 'side_standing_long_jump', 'Salto lateral parado', 'calisthenics', 'reps', 'beginner', array['conditioning','strength']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/side_standing_long_jump-0.webp', 'Em postura atlética, pés afastados na largura do quadril, joelhos e quadril levemente flexionados.
Incline para a direita e salte o mais longe possível para o lado, estendendo quadril, joelhos e tornozelos.
Aterrisse de frente para a mesma direção, amortecendo com as pernas.', '{"progressionTree":"side_standing_long_jump","progressionLevel":1,"maxLevel":5,"groups":["plyo","legs"],"catalog_no":110,"source_id":"Side_Standing_Long_Jump","steps":["Em postura atlética, pés afastados na largura do quadril, joelhos e quadril levemente flexionados.","Incline para a direita e salte o mais longe possível para o lado, estendendo quadril, joelhos e tornozelos.","Aterrisse de frente para a mesma direção, amortecendo com as pernas."],"tip":"Lidere o movimento com os braços e aterrisse com os pés afastados.","media_keys":["exercises/cali/side_standing_long_jump-0.webp","exercises/cali/side_standing_long_jump-1.webp"]}'::jsonb)
