values ('78091912-4920-50d6-95da-9e8a7dbe8ade', null, 'side_to_side_chins', 'Barra alternando os lados', 'calisthenics', 'reps', 'intermediate', array['strength','hypertrophy']::goal_kind[], array['Barra fixa']::text[], 'exercises/cali/side_to_side_chins-0.webp', 'Pegada pronada aberta, tronco inclinado ~30° para trás e peito aberto.
Puxe inclinando para a esquerda até a barra quase tocar a parte alta do peito, expirando.
Segure 1 s, desça e repita inclinando para a direita.', '{"progressionTree":"side_to_side_chins","progressionLevel":3,"maxLevel":5,"groups":["back"],"catalog_no":111,"source_id":"Side_To_Side_Chins","steps":["Pegada pronada aberta, tronco inclinado ~30° para trás e peito aberto.","Puxe inclinando para a esquerda até a barra quase tocar a parte alta do peito, expirando.","Segure 1 s, desça e repita inclinando para a direita."],"tip":"Leve o peito em direção a uma das mãos a cada repetição.","media_keys":["exercises/cali/side_to_side_chins-0.webp","exercises/cali/side_to_side_chins-1.webp"]}'::jsonb)
