values ('24858776-4ec5-540c-8b94-bfdc88bf2dfe', null, 'side_to_side_box_shuffle', 'Troca lateral sobre a caixa', 'calisthenics', 'reps', 'beginner', array['conditioning','strength']::goal_kind[], array['Caixa / plataforma']::text[], 'exercises/cali/side_to_side_box_shuffle-0.webp', 'De lado para a caixa, apoie o pé esquerdo no meio dela.
Salte para o outro lado: pé direito na caixa e esquerdo no chão.
Continue alternando de um lado para o outro balançando os braços.', '{"progressionTree":"side_to_side_box_shuffle","progressionLevel":1,"maxLevel":5,"groups":["plyo","legs"],"catalog_no":112,"source_id":"Side_to_Side_Box_Shuffle","steps":["De lado para a caixa, apoie o pé esquerdo no meio dela.","Salte para o outro lado: pé direito na caixa e esquerdo no chão.","Continue alternando de um lado para o outro balançando os braços."],"tip":"Use os braços para ritmo e mantenha os saltos contínuos.","media_keys":["exercises/cali/side_to_side_box_shuffle-0.webp","exercises/cali/side_to_side_box_shuffle-1.webp"]}'::jsonb)
