values ('e537f646-aeb5-546b-af94-da5ada1c76d6', null, 'single_arm_push_up', 'Flexão com um braço', 'calisthenics', 'reps', 'intermediate', array['strength','hypertrophy']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/single_arm_push_up-0.webp', 'Apoiado nas pontas dos pés e em um braço estendido sob o ombro; pés mais afastados que numa flexão normal.
Mão livre atrás das costas e postura firme.
Flexione o cotovelo e desça devagar até tocar o chão.
Estenda o braço voltando à posição inicial. Troque de braço.', '{"progressionTree":"single_arm_push_up","progressionLevel":3,"maxLevel":5,"groups":["chest","triceps"],"catalog_no":113,"source_id":"Single-Arm_Push-Up","steps":["Apoiado nas pontas dos pés e em um braço estendido sob o ombro; pés mais afastados que numa flexão normal.","Mão livre atrás das costas e postura firme.","Flexione o cotovelo e desça devagar até tocar o chão.","Estenda o braço voltando à posição inicial. Troque de braço."],"tip":"Afaste bem os pés para ter base; desça devagar.","media_keys":["exercises/cali/single_arm_push_up-0.webp","exercises/cali/single_arm_push_up-1.webp"]}'::jsonb)
