values ('7afab6d7-4688-59a3-90b7-40499a45bcde', null, 'single_leg_high_box_squat', 'Subida unilateral na caixa alta', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Caixa / plataforma']::text[], 'exercises/cali/single_leg_high_box_squat-0.webp', 'Coloque uma caixa alta e, se precisar, uma corda/elástico acima para equilíbrio.
Suba na caixa com uma perna até ficar totalmente em pé, deixando a outra solta.
Desça e suba com a mesma perna até completar a série; depois troque.', '{"progressionTree":"single_leg_high_box_squat","progressionLevel":1,"maxLevel":5,"groups":["legs"],"catalog_no":114,"source_id":"Single-Leg_High_Box_Squat","steps":["Coloque uma caixa alta e, se precisar, uma corda/elástico acima para equilíbrio.","Suba na caixa com uma perna até ficar totalmente em pé, deixando a outra solta.","Desça e suba com a mesma perna até completar a série; depois troque."],"tip":"Suba usando a perna de apoio, sem impulso da perna de baixo.","media_keys":["exercises/cali/single_leg_high_box_squat-0.webp","exercises/cali/single_leg_high_box_squat-1.webp"]}'::jsonb)
