values ('ed11e112-81f4-5fb1-a22a-25515af9f2e8', null, 'single_leg_hop_progression', 'Saltos unipodais sobre cones', 'calisthenics', 'reps', 'beginner', array['conditioning','strength']::goal_kind[], array['Cones / barreiras']::text[], 'exercises/cali/single_leg_hop_progression-0.webp', 'Enfileire cones à frente e fique equilibrado sobre uma perna, joelho oposto elevado.
Salte para frente por cima do cone, aterrissando com a mesma perna.
Use o contramovimento para emendar os saltos de cone em cone.
No fim, vire e volte com a outra perna.', '{"progressionTree":"single_leg_hop_progression","progressionLevel":1,"maxLevel":5,"groups":["plyo","legs"],"catalog_no":115,"source_id":"Single-Leg_Hop_Progression","steps":["Enfileire cones à frente e fique equilibrado sobre uma perna, joelho oposto elevado.","Salte para frente por cima do cone, aterrissando com a mesma perna.","Use o contramovimento para emendar os saltos de cone em cone.","No fim, vire e volte com a outra perna."],"tip":"Aterrisse e salte com a mesma perna, sem apoiar a outra.","media_keys":["exercises/cali/single_leg_hop_progression-0.webp","exercises/cali/single_leg_hop_progression-1.webp"]}'::jsonb)
