values ('732d47af-33dc-50a3-8c97-2b26f7d591e5', null, 'single_leg_stride_jump', 'Salto unipodal com pé na caixa', 'calisthenics', 'reps', 'beginner', array['conditioning','strength']::goal_kind[], array['Caixa / plataforma']::text[], 'exercises/cali/single_leg_stride_jump-0.webp', 'De lado para a caixa, apoie o pé de dentro sobre ela, perto da borda.
