values ('723604f7-8974-551d-8b16-00ccf0531903', null, 'single_leg_butt_kick', 'Salto unipodal com calcanhar no glúteo', 'calisthenics', 'reps', 'beginner', array['conditioning','strength']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/single_leg_butt_kick-0.webp', 'Em pé sobre uma perna, com o outro joelho elevado.
Salte estendendo quadril, joelho e tornozelo da perna de apoio.
No ar, flexione o joelho tentando tocar o calcanhar no glúteo.
Volte a perna para baixo do quadril e aterrisse.', '{"progressionTree":"single_leg_butt_kick","progressionLevel":1,"maxLevel":5,"groups":["plyo","legs"],"catalog_no":118,"source_id":"Single_Leg_Butt_Kick","steps":["Em pé sobre uma perna, com o outro joelho elevado.","Salte estendendo quadril, joelho e tornozelo da perna de apoio.","No ar, flexione o joelho tentando tocar o calcanhar no glúteo.","Volte a perna para baixo do quadril e aterrisse."],"tip":"A perna livre fica parada durante todo o drill.","media_keys":["exercises/cali/single_leg_butt_kick-0.webp","exercises/cali/single_leg_butt_kick-1.webp"]}'::jsonb)
