values ('bd550fa9-3956-52bb-9148-a8f0e7f34674', null, 'single_leg_glute_bridge', 'Ponte de glúteo unilateral', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/single_leg_glute_bridge-0.webp', 'Deitado com os pés no chão e joelhos flexionados.
Tire uma perna do chão puxando o joelho ao peito.
Empurre pelo calcanhar da perna de apoio estendendo o quadril e tirando os glúteos do chão.
Suba o máximo possível, pause e volte.', '{"progressionTree":"single_leg_glute_bridge","progressionLevel":1,"maxLevel":5,"groups":["legs"],"catalog_no":119,"source_id":"Single_Leg_Glute_Bridge","steps":["Deitado com os pés no chão e joelhos flexionados.","Tire uma perna do chão puxando o joelho ao peito.","Empurre pelo calcanhar da perna de apoio estendendo o quadril e tirando os glúteos do chão.","Suba o máximo possível, pause e volte."],"tip":"Empurre pelo calcanhar e mantenha o quadril nivelado.","media_keys":["exercises/cali/single_leg_glute_bridge-0.webp","exercises/cali/single_leg_glute_bridge-1.webp"]}'::jsonb)
