values ('8956a8c8-5724-5ed9-b2bc-cdc23ef302e2', null, 'single_leg_push_off', 'Impulsão unipodal na caixa', 'calisthenics', 'reps', 'beginner', array['conditioning','strength']::goal_kind[], array['Caixa / plataforma']::text[], 'exercises/cali/single_leg_push_off-0.webp', 'Em pé no chão com um pé apoiado na caixa, calcanhar perto da borda.
