values ('f3638abb-4f0b-5d69-8646-5aa89d3aeca5', null, 'sit_up', 'Abdominal completo (Sit-Up)', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/sit_up-0.webp', 'Deitado com os joelhos flexionados e os pés presos sob algo firme.
Mãos entrelaçadas atrás da cabeça.
Eleve o tronco até formar um "V" com as coxas, expirando; segure 1 s.
Desça devagar até a posição inicial, inspirando.', '{"progressionTree":"sit_up","progressionLevel":1,"maxLevel":5,"groups":["core"],"catalog_no":121,"source_id":"Sit-Up","steps":["Deitado com os joelhos flexionados e os pés presos sob algo firme.","Mãos entrelaçadas atrás da cabeça.","Eleve o tronco até formar um \"V\" com as coxas, expirando; segure 1 s.","Desça devagar até a posição inicial, inspirando."],"tip":"Não puxe a cabeça com as mãos; suba com o abdômen.","media_keys":["exercises/cali/sit_up-0.webp","exercises/cali/sit_up-1.webp"]}'::jsonb)
