values ('197cf316-ba47-58f4-beee-55274e12eadc', null, 'split_jump', 'Salto em afundo (Split Jump)', 'calisthenics', 'reps', 'beginner', array['conditioning','strength']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/split_jump-0.webp', 'Em posição de afundo: joelho da frente flexionado e o de trás quase no chão.
Estenda as duas pernas e salte o mais alto possível balançando os braços.
No ar, junte os pés e volte-os à posição inicial ao aterrissar.
Amorteça o impacto voltando ao afundo.', '{"progressionTree":"split_jump","progressionLevel":1,"maxLevel":5,"groups":["plyo","legs"],"catalog_no":123,"source_id":"Split_Jump","steps":["Em posição de afundo: joelho da frente flexionado e o de trás quase no chão.","Estenda as duas pernas e salte o mais alto possível balançando os braços.","No ar, junte os pés e volte-os à posição inicial ao aterrissar.","Amorteça o impacto voltando ao afundo."],"tip":"Joelho da frente sobre o meio do pé; amorteça voltando ao afundo.","media_keys":["exercises/cali/split_jump-0.webp","exercises/cali/split_jump-1.webp"]}'::jsonb)
