values ('c2a02c88-84f5-5371-87d3-43b790ba5d72', null, 'standing_long_jump', 'Salto horizontal parado', 'calisthenics', 'reps', 'beginner', array['conditioning','strength']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/standing_long_jump-0.webp', 'Em meio agachamento com os pés na largura dos ombros.
