values ('d8f8ec71-5174-5e61-b49b-8a5267cf5b37', null, 'standing_towel_triceps_extension', 'Extensão de tríceps com toalha', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/standing_towel_triceps_extension-0.webp', 'Em pé, segure uma ponta da toalha com as duas mãos e estenda os braços acima da cabeça.
