values ('e547a92b-a541-58b2-904f-7dafbdc18b3c', null, 'star_jump', 'Salto estrela (Star Jump)', 'calisthenics', 'reps', 'beginner', array['conditioning','strength']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/star_jump-0.webp', 'Em pé, pés na largura dos ombros e braços junto ao corpo.
