values ('01a6d79a-6b28-5dac-842a-391e68694643', null, 'step_up_with_knee_raise', 'Subida no banco com elevação de joelho', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Caixa / plataforma']::text[], 'exercises/cali/step_up_with_knee_raise-0.webp', 'De frente para uma caixa ou banco, pés juntos.
Suba com o pé esquerdo e estenda quadril e joelho para ficar em pé sobre o banco.
Ao subir, eleve o joelho direito o mais alto possível.
Desça e repita com a outra perna.', '{"progressionTree":"step_up_with_knee_raise","progressionLevel":1,"maxLevel":5,"groups":["legs"],"catalog_no":127,"source_id":"Step-up_with_Knee_Raise","steps":["De frente para uma caixa ou banco, pés juntos.","Suba com o pé esquerdo e estenda quadril e joelho para ficar em pé sobre o banco.","Ao subir, eleve o joelho direito o mais alto possível.","Desça e repita com a outra perna."],"tip":"Suba empurrando com a perna da frente; leve o outro joelho bem alto.","media_keys":["exercises/cali/step_up_with_knee_raise-0.webp","exercises/cali/step_up_with_knee_raise-1.webp"]}'::jsonb)
