insert into exercises (id, owner_id, slug, name_pt, modality, tracking, level, goals, equipment, media_url, instructions, attributes)
values ('b3623576-9003-5361-941d-45e06699379c', null, 'stride_jump_crossover', 'Salto cruzado sobre a caixa', 'calisthenics', 'reps', 'beginner', array['conditioning','strength']::goal_kind[], array['Caixa / plataforma']::text[], 'exercises/cali/stride_jump_crossover-0.webp', 'De lado para a caixa, com o pé de dentro sobre ela.
Balance os braços e empurre com a perna de cima, saltando o mais alto possível.
Aterrisse do outro lado da caixa: o pé que estava em cima vai ao chão e o outro sobe.
Repita cruzando de volta.', '{"progressionTree":"stride_jump_crossover","progressionLevel":1,"maxLevel":5,"groups":["plyo","legs"],"catalog_no":128,"source_id":"Stride_Jump_Crossover","steps":["De lado para a caixa, com o pé de dentro sobre ela.","Balance os braços e empurre com a perna de cima, saltando o mais alto possível.","Aterrisse do outro lado da caixa: o pé que estava em cima vai ao chão e o outro sobe.","Repita cruzando de volta."],"tip":"Impulsione com a perna de cima e troque de lado no ar.","media_keys":["exercises/cali/stride_jump_crossover-0.webp","exercises/cali/stride_jump_crossover-1.webp"]}'::jsonb)
