values ('404849fd-72ce-556e-bf69-d8097e8301d2', null, 'suspended_push_up', 'Flexão nas fitas de suspensão', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Argolas / suspensão']::text[], 'exercises/cali/suspended_push_up-0.webp', 'Prenda as fitas no alto, segure as alças e incline-se até a posição de prancha, o mais paralelo ao chão possível.
Desça devagar flexionando os cotovelos, com o tronco rígido.
Passe de 90° nos cotovelos, pause e estenda de volta.', '{"progressionTree":"suspended_push_up","progressionLevel":1,"maxLevel":5,"groups":["chest"],"catalog_no":130,"source_id":"Suspended_Push-Up","steps":["Prenda as fitas no alto, segure as alças e incline-se até a posição de prancha, o mais paralelo ao chão possível.","Desça devagar flexionando os cotovelos, com o tronco rígido.","Passe de 90° nos cotovelos, pause e estenda de volta."],"tip":"Tronco rígido; a instabilidade trabalha mais os estabilizadores.","media_keys":["exercises/cali/suspended_push_up-0.webp","exercises/cali/suspended_push_up-1.webp"]}'::jsonb)
