values ('24927561-e48b-564e-9324-dc2331ddb638', null, 'suspended_split_squat', 'Afundo búlgaro nas fitas de suspensão', 'calisthenics', 'reps', 'intermediate', array['strength','hypertrophy']::goal_kind[], array['Argolas / suspensão']::text[], 'exercises/cali/suspended_split_squat-0.webp', 'Alças a 45–75 cm do chão; de costas para elas, coloque o pé de trás na alça.
