values ('b8b3b292-2f6f-5057-bdcb-be43d117a1dc', null, 'split_squats', 'Afundo com troca de pernas (salto)', 'calisthenics', 'reps', 'intermediate', array['conditioning','strength']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/split_squats-0.webp', 'Em pé, salte para a posição de afundo com uma perna à frente e outra atrás, flexionando os joelhos.
