values ('34943aed-5854-5519-956b-695434a8f5ad', null, 'frog_hops', 'Saltos de sapo (Frog Hops)', 'calisthenics', 'reps', 'intermediate', array['conditioning','strength']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/frog_hops-0.webp', 'Mãos atrás da cabeça, agache mantendo o tronco ereto e a cabeça erguida.
Salte para frente alguns passos, sem subir demais.
Ao tocar o chão, amorteça com as pernas e salte de novo. Repita 5–10 vezes.', '{"progressionTree":"frog_hops","progressionLevel":3,"maxLevel":5,"groups":["plyo","legs"],"catalog_no":140,"source_id":"Frog_Hops","steps":["Mãos atrás da cabeça, agache mantendo o tronco ereto e a cabeça erguida.","Salte para frente alguns passos, sem subir demais.","Ao tocar o chão, amorteça com as pernas e salte de novo. Repita 5–10 vezes."],"tip":"Salte para frente, não para o alto; amorteça e emende.","media_keys":["exercises/cali/frog_hops-0.webp","exercises/cali/frog_hops-1.webp"]}'::jsonb)
