values ('148522e4-36ee-57bf-ab4e-be53db3e74e3', null, 'inchworm', 'Lagarta (Inchworm)', 'calisthenics', 'reps', 'beginner', array['endurance','skill']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/inchworm-0.webp', 'Em pé com os pés juntos, incline-se com as pernas estendidas e apoie as mãos no chão.
Caminhe com as mãos para frente até ficar em posição de flexão.
Mantendo as mãos no lugar, dê passos curtos com os pés até perto delas.
Repita o ciclo.', '{"progressionTree":"inchworm","progressionLevel":1,"maxLevel":5,"groups":["mobility","core"],"catalog_no":141,"source_id":"Inchworm","steps":["Em pé com os pés juntos, incline-se com as pernas estendidas e apoie as mãos no chão.","Caminhe com as mãos para frente até ficar em posição de flexão.","Mantendo as mãos no lugar, dê passos curtos com os pés até perto delas.","Repita o ciclo."],"tip":"Pernas estendidas: a flexão é só no quadril.","media_keys":["exercises/cali/inchworm-0.webp","exercises/cali/inchworm-1.webp"]}'::jsonb)
