values ('fdf84ae4-b911-54ed-a261-2ca5301d793a', null, 'scissor_kick', 'Tesoura (Scissor Kick)', 'calisthenics', 'reps', 'beginner', array['strength','hypertrophy']::goal_kind[], array['Peso corporal']::text[], 'exercises/cali/scissor_kick-0.webp', 'Deitado, braços estendidos ao lado com as palmas para baixo.
Eleve as pernas com os joelhos levemente flexionados até os calcanhares ficarem a ~15 cm do chão.
Suba uma perna a ~45° enquanto a outra desce perto do chão.
Alterne continuamente, como uma tesoura.', '{"progressionTree":"scissor_kick","progressionLevel":1,"maxLevel":5,"groups":["core"],"catalog_no":143,"source_id":"Scissor_Kick","steps":["Deitado, braços estendidos ao lado com as palmas para baixo.","Eleve as pernas com os joelhos levemente flexionados até os calcanhares ficarem a ~15 cm do chão.","Suba uma perna a ~45° enquanto a outra desce perto do chão.","Alterne continuamente, como uma tesoura."],"tip":"Braços parados e lombar colada no chão.","media_keys":["exercises/cali/scissor_kick-0.webp","exercises/cali/scissor_kick-1.webp"]}'::jsonb)
